INSERT INTO "release_notes" ("version", "status", "content", "created_at", "updated_at", "published_at") VALUES
('0.1.3', 'published', '{"items":[{"id":"soundboard","category":"new","highlight":true,"media":{"kind":"image","url":"https://raw.githubusercontent.com/alanaraujo-bit/Alga-Meet/main/docs/screenshots/soundboard/05-playing.png"}},{"id":"sons-proprios","category":"new","highlight":false,"media":null},{"id":"anti-spam","category":"improved","highlight":false,"media":null}],"text":{"pt-BR":{"title":"Soundboard nos espaços","summary":"Toque sons para todo mundo na call, com o seu próprio som cortado em segundos.","items":{"soundboard":{"title":"Soundboard na call","body":"Um botão na barra da call toca sons para todo mundo. O emoji sobe no seu avatar, e cada pessoa ajusta o volume ou silencia só para si.","alt":"A call com o painel do soundboard aberto e um som tocando."},"sons-proprios":{"title":"Seus próprios sons","body":"Arraste um áudio, corte até 5 segundos na forma de onda e pronto: o volume é igualado sozinho."},"anti-spam":{"title":"Sem bagunça","body":"Um intervalo curto entre sons e no máximo três ao mesmo tempo por canal. Cargos ganham \"Usar o soundboard\" e \"Gerenciar sons\"."}}}}}'::jsonb, '2026-11-05T10:00:00Z', '2026-11-05T10:00:00Z', '2026-11-05T10:00:00Z'),
('0.1.4', 'published', '{"items":[{"id":"atividade","category":"new","highlight":true,"media":{"kind":"image","url":"https://raw.githubusercontent.com/alanaraujo-bit/Alga-Meet/main/docs/screenshots/2026-11-05-activity-members-v2.png"}},{"id":"ativo-agora","category":"new","highlight":false,"media":null},{"id":"status","category":"new","highlight":false,"media":null},{"id":"privacidade-atividade","category":"improved","highlight":false,"media":null}],"text":{"pt-BR":{"title":"Veja o que a galera está fazendo","summary":"Atividade em tempo real, status personalizado e um perfil que conta mais sobre cada pessoa.","items":{"atividade":{"title":"Atividade em tempo real","body":"O jogo ou app aberto aparece no perfil, na lista de amigos e na sala de voz, com ícone e cronômetro. Só o nome do app sai do seu PC, nunca o título da janela.","alt":"A lista de membros mostrando quem está jogando e criando agora."},"ativo-agora":{"title":"Ativo agora","body":"Na aba Amigos, quem está jogando, criando ou numa sala, com \"Entrar\" direto."},"status":{"title":"Status personalizado","body":"Emoji e texto com prazo: 30 minutos, 1 hora, hoje ou para sempre."},"privacidade-atividade":{"title":"Você decide o que aparece","body":"Cada app tem seu interruptor em Configurações › Atividade. \"Pausar 1 h\" e \"Ocultar\" no próprio cartão."}}}}}'::jsonb, '2026-11-05T14:00:00Z', '2026-11-05T14:00:00Z', '2026-11-05T14:00:00Z'),
('0.1.5', 'published', '{"items":[{"id":"updater","category":"fixed","highlight":true,"media":null},{"id":"ptt","category":"fixed","highlight":false,"media":null}],"text":{"pt-BR":{"title":"A atualização automática voltou","summary":"Um conserto importante para as próximas versões chegarem sozinhas.","items":{"updater":{"title":"Atualizações chegam sozinhas de novo","body":"A 0.1.3 e a 0.1.4 saíram sem uma peça do atualizador. Corrigido, e o build agora se recusa a publicar um pacote incompleto."},"ptt":{"title":"Atalho de falar","body":"O push-to-talk global voltou a funcionar desde a abertura do app."}}}}}'::jsonb, '2026-11-05T16:00:00Z', '2026-11-05T16:00:00Z', '2026-11-05T16:00:00Z'),
('0.1.6', 'published', '{"items":[{"id":"eco","category":"new","highlight":true,"media":{"kind":"image","url":"https://raw.githubusercontent.com/alanaraujo-bit/Alga-Meet/main/docs/screenshots/2026-11-05-fundamentals-eco-editor-v10.png"}},{"id":"olhar-antes","category":"new","highlight":true,"media":null},{"id":"notificacoes","category":"improved","highlight":false,"media":null},{"id":"fila-mensagens","category":"improved","highlight":false,"media":null},{"id":"convites","category":"improved","highlight":false,"media":null}],"text":{"pt-BR":{"title":"Conheça o Eco","summary":"O mascote do Alga Meet chegou, junto com um app mais calmo e mais fácil de chamar a galera.","items":{"eco":{"title":"Seu Eco","body":"Quem não tem foto aparece como um Eco. Monte o seu em Configurações › Minha conta: cor, olhos, cabelo e acessório.","alt":"O editor do Eco com cores, olhos, cabelos e acessórios."},"olhar-antes":{"title":"Olhe antes de entrar","body":"Um clique na sala de voz mostra quem está lá e o que está fazendo, sem ninguém te ver. Dá para testar o microfone antes de entrar."},"notificacoes":{"title":"Notificações calmas","body":"Cada espaço tem o seu nível: tudo, só @menções ou silenciado. Também dá para silenciar por 1 hora."},"fila-mensagens":{"title":"Mensagem que sempre chega","body":"Sem internet, a mensagem espera e sai sozinha quando a conexão volta, uma vez só."},"convites":{"title":"Convites que abrem","body":"O link mostra quem te chamou e para onde, com \"Enviar no WhatsApp\"."}}}}}'::jsonb, '2026-11-05T18:00:00Z', '2026-11-05T18:00:00Z', '2026-11-05T18:00:00Z'),
('0.1.7', 'published', '{"items":[{"id":"instalador","category":"new","highlight":true,"media":null},{"id":"atualizar","category":"improved","highlight":false,"media":null},{"id":"desinstalar","category":"improved","highlight":false,"media":null}],"text":{"pt-BR":{"title":"Instalar com a cara do Alga Meet","summary":"Sai o assistente genérico do Windows, entra uma janela nossa, com o Eco.","items":{"instalador":{"title":"Monte seu Eco enquanto instala","body":"Um clique e pronto. Enquanto os arquivos copiam, você escolhe o seu Eco, e o app já abre com ele."},"atualizar":{"title":"Atualizar sem susto","body":"Ao reiniciar para atualizar, um cartão pequeno com o Eco mostra o progresso e o app volta sozinho."},"desinstalar":{"title":"Desinstalar com cuidado","body":"Você escolhe se apaga os dados deste computador. Sua conta continua salva."}}}}}'::jsonb, '2026-11-05T20:00:00Z', '2026-11-05T20:00:00Z', '2026-11-05T20:00:00Z'),
('0.1.8', 'published', '{"items":[{"id":"loja","category":"new","highlight":true,"media":null},{"id":"presentes","category":"new","highlight":false,"media":null},{"id":"fps-jogos","category":"fixed","highlight":true,"media":null}],"text":{"pt-BR":{"title":"A loja e uma transmissão de jogo lisa","summary":"A coleção Hora Azul chegou, e jogo pesado não derruba mais a sua tela compartilhada.","items":{"loja":{"title":"Loja Hora Azul","body":"Auras de voz, decorações de perfil, ícones e cores do app. Prove em você, no perfil e na call, antes de decidir."},"presentes":{"title":"Presentes","body":"Dê um item ou o Plus para um amigo, com uma revelação animada quando ele abre."},"fps-jogos":{"title":"Jogo pesado a 60 fps","body":"Com um jogo pesado aberto, a transmissão caía para 5–9 fps. Agora fica perto de 60, sem pesar no jogo."}}}}}'::jsonb, '2026-11-05T22:00:00Z', '2026-11-05T22:00:00Z', '2026-11-05T22:00:00Z'),
('0.1.9', 'published', '{"items":[{"id":"cinema","category":"new","highlight":true,"media":null},{"id":"legendas","category":"new","highlight":false,"media":null}],"text":{"pt-BR":{"title":"Sala de Cinema","summary":"Assista a um filme baixado junto com os amigos, na call, todo mundo no mesmo frame.","items":{"cinema":{"title":"Assista junto, no mesmo frame","body":"Abra um filme ou série do seu PC e todo mundo na call assiste em qualidade nativa, sincronizado. As peças vão direto entre vocês, criptografadas."},"legendas":{"title":"Legendas e áudios","body":"Legendas SRT e ASS, troca de áudio do filme e o som da call abaixando sozinho nas falas."}}}}}'::jsonb, '2026-11-06T08:00:00Z', '2026-11-06T08:00:00Z', '2026-11-06T08:00:00Z'),
('0.1.10', 'published', '{"items":[{"id":"botao-cinema","category":"fixed","highlight":true,"media":null}],"text":{"pt-BR":{"title":"O botão Cinema aparece","summary":"Uma correção rápida para a Sala de Cinema.","items":{"botao-cinema":{"title":"Botão Cinema na call","body":"O botão não aparecia no dock da chamada. Agora aparece."}}}}}'::jsonb, '2026-11-06T09:49:25Z', '2026-11-06T09:49:25Z', '2026-11-06T09:49:25Z'),
('0.1.11', 'published', '{"items":[{"id":"series","category":"new","highlight":true,"media":null},{"id":"proximo-episodio","category":"improved","highlight":false,"media":null}],"text":{"pt-BR":{"title":"Séries no Cinema","summary":"Abra um episódio e a série inteira vem junto.","items":{"series":{"title":"A série inteira na ficha","body":"Temporadas, episódios já assistidos e \"Continuar a série\", sem escolher arquivo por arquivo."},"proximo-episodio":{"title":"Próximo episódio sozinho","body":"Nos créditos, o próximo começa sozinho, inclusive entre temporadas."}}}}}'::jsonb, '2026-11-07T14:24:34Z', '2026-11-07T14:24:34Z', '2026-11-07T14:24:34Z'),
('0.1.12', 'published', '{"items":[{"id":"perfil","category":"new","highlight":true,"media":{"kind":"image","url":"https://raw.githubusercontent.com/alanaraujo-bit/Alga-Meet/main/docs/screenshots/2026-11-07-profile-full-v1.png"}},{"id":"popover-voz","category":"improved","highlight":false,"media":null}],"text":{"pt-BR":{"title":"Perfil de quem você conhece","summary":"Saiba mais sobre amigos e membros com um clique.","items":{"perfil":{"title":"Perfil completo","body":"Membro desde, amigos desde, o que vocês têm em comum e abas animadas.","alt":"O perfil completo de um amigo, com atividade agora e o que vocês têm em comum."},"popover-voz":{"title":"Ver perfil na call","body":"Clique em quem está na voz ou num assento da chamada para abrir o perfil."}}}}}'::jsonb, '2026-11-07T17:56:15Z', '2026-11-07T17:56:15Z', '2026-11-07T17:56:15Z'),
('0.1.13', 'published', '{"items":[{"id":"checkout","category":"new","highlight":true,"media":null}],"text":{"pt-BR":{"title":"Pague sem sair do app","summary":"Plus, itens, presentes e a Casa do espaço, com cartão ou Pix.","items":{"checkout":{"title":"Checkout no app","body":"Cartão com os campos seguros do Mercado Pago ou Pix com QR e copia e cola. Confirmou, liberou."}}}}}'::jsonb, '2026-11-08T22:43:40Z', '2026-11-08T22:43:40Z', '2026-11-08T22:43:40Z'),
('0.1.14', 'published', '{"items":[{"id":"checkout-visual","category":"improved","highlight":true,"media":null}],"text":{"pt-BR":{"title":"Pagamento com a cara do app","summary":"Os campos do cartão agora combinam com o resto do Alga Meet.","items":{"checkout-visual":{"title":"Campos que parecem do app","body":"Nome e CPF nativos, campos do cartão no mesmo estilo e nada de blocos brancos."}}}}}'::jsonb, '2026-11-08T23:07:26Z', '2026-11-08T23:07:26Z', '2026-11-08T23:07:26Z'),
('0.1.15', 'published', '{"items":[{"id":"novidades","category":"new","highlight":true,"media":null},{"id":"aviso-atualizacao","category":"improved","highlight":true,"media":null},{"id":"reacoes","category":"new","highlight":false,"media":null}],"text":{"pt-BR":{"title":"Cada atualização, contada por nós","summary":"Agora você vê o que mudou logo depois de atualizar, e pode dizer o que achou.","items":{"novidades":{"title":"Central de Novidades","body":"Todas as versões num lugar só, com o que é novo, o que melhorou e o que foi corrigido. Fica na barra da esquerda, no ícone de brilho logo abaixo dos seus espaços."},"aviso-atualizacao":{"title":"Atualização sem interromper","body":"Quando uma versão nova fica pronta, um aviso discreto aparece no topo. Você reinicia quando quiser, e nada aparece no meio de uma call."},"reacoes":{"title":"Diga o que achou","body":"Gostou ou não de uma novidade? Um toque e a equipe fica sabendo. Dá para mudar de ideia depois."}}}}}'::jsonb, now(), now(), now())
